CREATE OR REPLACE FUNCTION public.copilot_amount_cache(amount text,currency text,fallback text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE n numeric; BEGIN BEGIN n:=amount::numeric; EXCEPTION WHEN OTHERS THEN RETURN fallback; END; IF n<=0 THEN RETURN fallback; END IF; RETURN upper(coalesce(currency,''))||' '||CASE WHEN n>=1000000000 THEN round(n/1000000000,3)::float8::text||'bn' WHEN n>=1000000 THEN round(n/1000000,3)::float8::text||'m' ELSE to_char(n,'FM999,999,999,999,990.999') END; END $$;
CREATE OR REPLACE FUNCTION public.copilot_tenor_cache(start_date text,maturity text,fallback text) RETURNS text LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE years numeric; BEGIN IF coalesce(start_date,'')='' OR coalesce(maturity,'')='' THEN RETURN fallback; END IF; BEGIN years:=round(((maturity::date-start_date::date)/365.25)*2)/2; EXCEPTION WHEN OTHERS THEN RETURN fallback; END; IF years<=0 THEN RETURN fallback; END IF; RETURN years::float8::text||'Y'; END $$;
REVOKE ALL ON FUNCTION public.copilot_amount_cache(text,text,text),public.copilot_tenor_cache(text,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.copilot_amount_cache(text,text,text),public.copilot_tenor_cache(text,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.copilot_decide(_change uuid,_approve boolean) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.copilot_changes; d public.deals; deal text; st jsonb; path text; pos integer; decision text; BEGIN SELECT t.deal_id INTO deal FROM public.copilot_changes x JOIN public.copilot_threads t ON t.id=x.thread_id WHERE x.id=_change; IF deal IS NULL OR NOT public.copilot_editor(deal) THEN RAISE EXCEPTION 'Term-edit rights required'; END IF; SELECT * INTO d FROM public.deals WHERE id=deal FOR UPDATE; SELECT * INTO c FROM public.copilot_changes WHERE id=_change FOR UPDATE; IF c.status<>'pending' THEN RAISE EXCEPTION 'Change already decided'; END IF; IF _approve THEN IF public.copilot_context(deal)->>c.field IS DISTINCT FROM c.before_value THEN RAISE EXCEPTION 'Deal changed; request a new proposal'; END IF; st:=d.bdt_state; IF st IS NULL OR st->'f' IS NULL THEN RAISE EXCEPTION 'Save the term sheet before approving changes'; END IF; path:=CASE c.field WHEN 'currency' THEN 'IssuanceDataGroup/Issuance/SpecifiedCurrency' WHEN 'size' THEN 'IssuanceDataGroup/Issuance/TotalAggregateAmount/Value' WHEN 'coupon' THEN 'IssuanceDataGroup/Product/InterestPayment/FixedRatePayment/InterestRate' WHEN 'maturity' THEN 'IssuanceDataGroup/Product/Maturity/MaturityDate' WHEN 'governingLaw' THEN 'IssuanceDataGroup/Issuance/GoverningLaw/CountryCode' ELSE NULL END; IF path IS NOT NULL THEN st:=jsonb_set(st,ARRAY['f',path],to_jsonb(c.after_value),true); ELSIF c.field='issuer' THEN SELECT ord::integer-1 INTO pos FROM jsonb_array_elements(coalesce(st->'parties','[]')) WITH ORDINALITY x(v,ord) WHERE v->'Roles' ? 'ISSUER' LIMIT 1; IF pos IS NULL THEN st:=jsonb_set(st,'{parties}',coalesce(st->'parties','[]')||jsonb_build_array(jsonb_build_object('PartyName',c.after_value,'LEIIdentifier','','Roles',jsonb_build_array('ISSUER'),'Ratings','[]'::jsonb))); ELSE st:=jsonb_set(st,ARRAY['parties',pos::text,'PartyName'],to_jsonb(c.after_value)); END IF; st:=jsonb_set(st,'{deal}',to_jsonb(c.after_value)); ELSE SELECT ord::integer-1 INTO pos FROM jsonb_array_elements(coalesce(st->'ids','[]')) WITH ORDINALITY x(v,ord) WHERE v->>'Type'='ISIN' LIMIT 1; IF pos IS NULL THEN st:=jsonb_set(st,'{ids}',coalesce(st->'ids','[]')||jsonb_build_array(jsonb_build_object('Type','ISIN','Value',c.after_value))); ELSE st:=jsonb_set(st,ARRAY['ids',pos::text,'Value'],to_jsonb(c.after_value)); END IF; END IF; UPDATE public.deals SET bdt_state=st,issuer_name=CASE WHEN c.field='issuer' THEN c.after_value ELSE issuer_name END,currency=CASE WHEN c.field='currency' THEN c.after_value ELSE currency END,size=CASE WHEN c.field IN ('size','currency') THEN public.copilot_amount_cache(st->'f'->>'IssuanceDataGroup/Issuance/TotalAggregateAmount/Value',st->'f'->>'IssuanceDataGroup/Issuance/SpecifiedCurrency',size) ELSE size END,coupon=CASE WHEN c.field='coupon' THEN c.after_value||'%' ELSE coupon END,tenor=CASE WHEN c.field='maturity' THEN public.copilot_tenor_cache(coalesce(st->'f'->>'IssuanceDataGroup/Issuance/IssueDate',st->'f'->>'IssuanceDataGroup/Issuance/SettlementDate'),c.after_value,tenor) ELSE tenor END,maturity_date=CASE WHEN c.field='maturity' THEN c.after_value ELSE maturity_date END,isin=CASE WHEN c.field='isin' THEN c.after_value ELSE isin END,governing_law=CASE WHEN c.field='governingLaw' THEN CASE c.after_value WHEN 'GB' THEN 'ENGLISH_LAW' WHEN 'US' THEN 'NEW_YORK_LAW' WHEN 'FR' THEN 'FRENCH_LAW' WHEN 'DE' THEN 'GERMAN_LAW' WHEN 'CH' THEN 'SWISS_LAW' ELSE '' END ELSE governing_law END WHERE id=deal; END IF; decision:=CASE WHEN _approve THEN 'approved' ELSE 'rejected' END; UPDATE public.copilot_changes SET status=decision,decided_by=auth.uid(),decided_at=now() WHERE id=_change; INSERT INTO public.audit_log(id,action,entity_type,entity_id,user_id,timestamp,details) VALUES(gen_random_uuid()::text,'copilot_'||decision,'deal',deal,auth.uid()::text,now(),jsonb_build_object('changeId',_change,'field',c.field,'before',c.before_value,'after',c.after_value)::text); RETURN decision; END $$;